        for (int i = 0; values &amp;&amp; i &lt; v.size(); ++i) values = values &amp;&amp; (back(i) == v(i));
        check("blitz::Array&lt;double,1&gt;(8)    shape + values", shape &amp;&amp; values);
    }

    // 2D matrix (chunked + gzip) ────────────────────────────────────────────
    {
        Mat2D&lt;short&gt; M(3, 4);
        for (int r = 0; r &lt; M.rows(); ++r)
